css:
.pg { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 32px; }
.pg__b { min-width: 44px; padding: 10px 16px; text-align: center; border: 1px solid var(--line); border-radius: var(--radius-input); background: var(--card); font: 700 16px/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; color: var(--accent); text-decoration: none; transition: background var(--hcm-dur) var(--hcm-ease), color var(--hcm-dur) var(--hcm-ease); }
.pg__b:hover { border-color: var(--accent); }
.pg__b.is-active { background: var(--accent); border-color: var(--accent); color: #fff; }
.pg__b.is-off { opacity: .45; }
